import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Button, Card, ListGroup } from 'react-bootstrap';
import { 
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { 
  addField, 
  reorderFields, 
  deleteField 
} from '../../store/formSlice';

const fieldTypes = [
  { type: 'text', label: '📝 Text', icon: 'T' },
  { type: 'email', label: '📧 Email', icon: 'E' },
  { type: 'number', label: '🔢 Number', icon: '#' },
  { type: 'date', label: '📅 Date', icon: 'D' },
  { type: 'checkbox', label: '☑️ Checkbox', icon: '✓' },
  { type: 'radio', label: '⭕ Radio Group', icon: '○' },
  { type: 'dropdown', label: '📋 Dropdown', icon: '▼' },
];

function SortableFieldItem({ field, onSelect, isSelected }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({ id: field.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    cursor: 'grab',
  };

  const dispatch = useDispatch();

  const getFieldIcon = (type) => {
    const fieldType = fieldTypes.find(ft => ft.type === type);
    return fieldType ? fieldType.icon : '?';
  };

  return (
    <ListGroup.Item
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      action
      active={isSelected}
      onClick={() => onSelect(field.id)}
      className="d-flex justify-content-between align-items-center"
    >
      <div>
        <span className="me-2">{getFieldIcon(field.type)}</span>
        {field.label || `Unnamed ${field.type} field`}
      </div>
      <Button
        variant="outline-danger"
        size="sm"
        onClick={(e) => {
          e.stopPropagation();
          dispatch(deleteField(field.id));
        }}
      >
        ×
      </Button>
    </ListGroup.Item>
  );
}

export default function FieldList({ onSelectField }) {
  const dispatch = useDispatch();
  const fields = useSelector((state) => state.form.fields);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      dispatch(reorderFields({ activeId: active.id, overId: over.id }));
    }
  };

  return (
    <Card>
      <Card.Header className="d-flex justify-content-between align-items-center">
        <h5 className="mb-0">Add Fields</h5>
        <small>{fields.length} fields</small>
      </Card.Header>
      <Card.Body>
        <div className="d-grid gap-2 mb-3">
          {fieldTypes.map((fieldType) => (
            <Button
              key={fieldType.type}
              variant="outline-primary"
              size="sm"
              onClick={() => dispatch(addField({ type: fieldType.type }))}
            >
              {fieldType.label}
            </Button>
          ))}
        </div>

        <h6>Field Order (Drag to reorder)</h6>
        
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext
            items={fields.map(f => f.id)}
            strategy={verticalListSortingStrategy}
          >
            <ListGroup>
              {fields.map((field) => (
                <SortableFieldItem
                  key={field.id}
                  field={field}
                  onSelect={onSelectField}
                  isSelected={selectedFieldId === field.id}
                  onClick={() => onSelectField(field.id)}
                />
              ))}
              {fields.length === 0 && (
                <ListGroup.Item className="text-muted text-center">
                  No fields added yet. Click buttons above to add fields.
                </ListGroup.Item>
              )}
            </ListGroup>
          </SortableContext>
        </DndContext>
      </Card.Body>
    </Card>
  );
}
